#include <fcntl.h>   // open、O_RDONLY
#include <unistd.h>  // close
#include <cstdio>    // printf、perror

int main() {
    int fd = open("gpu-kernel-lab/cpp-basics/process.cpp", O_RDONLY);

    if (fd < 0) {
        std::perror("open");
        return 1;
    }

    std::printf("fd=%d\n", fd);

    if (close(fd) < 0) {
        std::perror("close");
        return 1;
    }

    return 0;
}
